import{_ as a,o as s,c as i,ag as o}from"./chunks/framework.BwSLX4ak.js";const h=JSON.parse('{"title":"QQMusic","description":"","frontmatter":{},"headers":[],"relativePath":"allmusic/qqmusic.md","filePath":"allmusic/qqmusic.md"}'),c={name:"allmusic/qqmusic.md"};function t(l,e,d,n,p,u){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="qqmusic" tabindex="-1">QQMusic <a class="header-anchor" href="#qqmusic" aria-label="Permalink to &quot;QQMusic&quot;">​</a></h1><p>AllMusic_QQMusic 的 API ID 是 <code>qqmusic</code>。它支持关键词搜索、歌曲信息、专辑封面、时间轴歌词与 QQ 音乐返回的可用播放地址，也能读取支持的歌曲或歌单链接中的标识。</p><h2 id="搜索和默认音乐源" tabindex="-1">搜索和默认音乐源 <a class="header-anchor" href="#搜索和默认音乐源" aria-label="Permalink to &quot;搜索和默认音乐源&quot;">​</a></h2><p>按<a href="./#安装">音乐源安装步骤</a>加载 JAR 后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search qqmusic 稻香</span></span></code></pre></div><p>若 AllMusic 的 <code>defaultApi</code> 已设为 <code>qqmusic</code>，可以省略 API ID：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/music search 稻香</span></span></code></pre></div><p>歌曲通常使用 QQ 音乐的 <code>songmid</code>，歌单使用数字 ID。当前实现可以从 <code>songmid</code>、<code>disstid</code> / <code>dissid</code> 参数及支持的 song、songdetail、playlist、taoge 路径提取标识。浏览器分享页链接不一定就是音频地址，应交给音乐源解析。</p><h2 id="cookie-与播放" tabindex="-1">Cookie 与播放 <a class="header-anchor" href="#cookie-与播放" aria-label="Permalink to &quot;Cookie 与播放&quot;">​</a></h2><p>QQMusic 读取 AllMusic 已加载的 Cookie 列表，即 AllMusic 自己的 <code>cookie.json</code> 数据。QQMusic 的 <code>reload(File)</code> 没有独立配置文件逻辑，不需要额外创建 <code>qqmusic.yml</code>。</p><p>需要登录态时，按 AllMusic 的 Cookie 格式保存当前 QQ 音乐账号的数据，再用当前 AllMusic 的重载方式或正常重启加载。没有 Cookie 时仍可能获得公开搜索结果或部分歌曲地址；具体可播放范围取决于 QQ 音乐返回结果和账号权限。扩展不会提供平台未正常授权返回的播放链接。</p><p>不要把真实 Cookie 写入本网站的示例或提交到公开仓库。代码中的 <code>QQSong.debug</code> 默认是 <code>false</code>。</p><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>把与你的 AllMusic 版本对应的核心 JAR 放入项目的 <code>libs/</code>，然后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gradlew.bat build</span></span></code></pre></div><p>Linux/macOS 使用 <code>./gradlew build</code>。产物在 <code>build/libs/</code>，当前源码的版本号由 <code>build.gradle</code> 决定；不要照抄旧 README 中的固定文件名。编译依赖为 <code>compileOnly</code>，运行时由 AllMusic 提供相应核心与公共库。</p><p><a href="https://github.com/hutuyee/AllMusic_QQMusic" target="_blank" rel="noreferrer">QQMusic 源码</a> · <a href="./troubleshooting.html">常见问题</a></p>',17)])])}const m=a(c,[["render",t]]);export{h as __pageData,m as default};
